Status decodeTablespaceHeaderBuffer(const uint8_t *buffer,
                                   TablespaceHeader *header_out,
                                   uint16_t *version_out,
                                   ErrorContext *ctx)
{
    if (!buffer || !header_out)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Null tablespace header buffer");
        return Status::INVALID_ARGUMENT;
    }

    const auto *page_header = reinterpret_cast<const PageHeader *>(buffer);
    uint16_t version = page_header->version;
    if (version_out != nullptr)
    {
        *version_out = version;
    }

    if (version == TABLESPACE_HEADER_VERSION_V1)
    {
        const auto *legacy = reinterpret_cast<const TablespaceHeaderV1 *>(buffer);
        std::memset(header_out, 0, sizeof(*header_out));
        header_out->page_header = legacy->page_header;
        std::memcpy(header_out->tablespace_name, legacy->tablespace_name,
                    sizeof(legacy->tablespace_name));
        header_out->tablespace_name[sizeof(legacy->tablespace_name)] = '\0';
        header_out->tablespace_uuid = legacy->tablespace_uuid;
        header_out->database_uuid = legacy->database_uuid;
        header_out->tablespace_id = legacy->tablespace_id;
        header_out->page_size = legacy->page_size;
        header_out->creation_time = legacy->creation_time;
        header_out->last_checkpoint = legacy->last_checkpoint;
        header_out->autoextend_enabled = legacy->autoextend_enabled;
        header_out->autoextend_size_mb = legacy->autoextend_size_mb;
        header_out->max_size_mb = legacy->max_size_mb;
        std::memcpy(header_out->reserved1, legacy->reserved1, sizeof(legacy->reserved1));
        header_out->total_pages = legacy->total_pages;
        header_out->free_pages = legacy->free_pages;
        header_out->next_page_number = legacy->next_page_number;
        header_out->fsm_root_page = legacy->fsm_root_page;
        header_out->oldest_transaction_id = legacy->oldest_transaction_id;
        header_out->latest_completed_xid = legacy->latest_completed_xid;
        std::memcpy(header_out->reserved2, legacy->reserved2, sizeof(legacy->reserved2));
        return Status::OK;
    }

    if (version == TABLESPACE_HEADER_VERSION_V2)
    {
        std::memcpy(header_out, buffer, sizeof(*header_out));
        return Status::OK;
    }

    SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT,
                     ("Unsupported tablespace header version: " + std::to_string(version)).c_str());
    return Status::INVALID_ARGUMENT;
}
bool isZeroUuidLocal(const ID& id) {
    for (auto b : id.bytes) {
        if (b != 0) {
            return false;
        }
    }
    return true;
}

ID resolveOwnerFromSession(CatalogManager* catalog, ErrorContext* ctx) {
    auto* conn = ConnectionContext::getCurrent();
    if (conn) {
        auto security_ctx = conn->getCurrentSecurityContext();
        if (!isZeroUuidLocal(security_ctx.effective_user_id)) {
            return security_ctx.effective_user_id;
        }
    }
    return catalog->getSystemUserId(ctx);
}

std::string normalizeResolverName(const std::string& name, bool name_is_delimited) {
    return name_is_delimited ? name : IdentifierUtils::toUpper(name);
}

std::vector<std::string> splitSchemaPath(const std::string& path) {
    std::vector<std::string> components;
    if (path.empty()) {
        return components;
    }
    size_t start = 0;
    while (start < path.size()) {
        size_t dot = path.find('.', start);
        if (dot == std::string::npos) {
            dot = path.size();
        }
        if (dot > start) {
            components.emplace_back(path.substr(start, dot - start));
        }
        start = dot + 1;
    }
    return components;
}

uint32_t readUint32LE(const uint8_t* data) {
    return static_cast<uint32_t>(data[0]) |
           (static_cast<uint32_t>(data[1]) << 8) |
           (static_cast<uint32_t>(data[2]) << 16) |
           (static_cast<uint32_t>(data[3]) << 24);
}

// Binary list encoding for TOAST: [count:u32][len:u32][bytes...]...
std::string encodeStringList(const std::vector<std::string>& items) {
    std::string out;
    out.resize(4);
    sblr::writeInt32(reinterpret_cast<uint8_t*>(out.data()),
                     static_cast<uint32_t>(items.size()));
    for (const auto& item : items) {
        if (item.size() > UINT32_MAX) {
            continue;
        }
        size_t offset = out.size();
        out.resize(offset + 4 + item.size());
        sblr::writeInt32(reinterpret_cast<uint8_t*>(&out[offset]),
                         static_cast<uint32_t>(item.size()));
        if (!item.empty()) {
            std::memcpy(&out[offset + 4], item.data(), item.size());
        }
    }
    return out;
}

bool decodeStringList(const std::string& blob, std::vector<std::string>& out) {
    out.clear();
    if (blob.size() < 4) {
        return false;
    }
    const uint8_t* data = reinterpret_cast<const uint8_t*>(blob.data());
    size_t offset = 0;
    uint32_t count = readUint32LE(data);
    offset += 4;
    out.reserve(count);
    for (uint32_t i = 0; i < count; ++i) {
        if (offset + 4 > blob.size()) {
            return false;
        }
        uint32_t len = readUint32LE(data + offset);
        offset += 4;
        if (offset + len > blob.size()) {
            return false;
        }
        out.emplace_back(reinterpret_cast<const char*>(data + offset), len);
        offset += len;
    }
    return offset == blob.size();
}

std::string encodeIdList(const std::vector<ID>& ids) {
    std::string out;
    out.resize(4);
    sblr::writeInt32(reinterpret_cast<uint8_t*>(out.data()),
                     static_cast<uint32_t>(ids.size()));
    for (const auto& id : ids) {
        size_t offset = out.size();
        out.resize(offset + id.bytes.size());
        std::memcpy(&out[offset], id.bytes.data(), id.bytes.size());
    }
    return out;
}

bool decodeIdList(const std::string& blob, std::vector<ID>& out) {
    out.clear();
    if (blob.size() < 4) {
        return false;
    }
    const uint8_t* data = reinterpret_cast<const uint8_t*>(blob.data());
    size_t offset = 0;
    uint32_t count = readUint32LE(data);
    offset += 4;
    if (blob.size() < offset + (static_cast<size_t>(count) * ID{}.bytes.size())) {
        return false;
    }
    out.reserve(count);
    for (uint32_t i = 0; i < count; ++i) {
        ID id{};
        std::memcpy(id.bytes.data(), data + offset, id.bytes.size());
        offset += id.bytes.size();
        out.push_back(id);
    }
    return offset == blob.size();
}

struct TypeDescriptorBlob {
    DataType type = DataType::INT32;
    uint32_t precision = 0;
    uint32_t scale = 0;
};

std::string encodeTypeDescriptor(DataType type, uint32_t precision, uint32_t scale) {
    std::string out;
    out.resize(1 + 4 + 4);
    out[0] = static_cast<char>(static_cast<uint8_t>(type));
    sblr::writeInt32(reinterpret_cast<uint8_t*>(&out[1]), precision);
    sblr::writeInt32(reinterpret_cast<uint8_t*>(&out[5]), scale);
    return out;
}

bool decodeTypeDescriptor(const std::string& blob, TypeDescriptorBlob& out) {
    if (blob.size() < 9) {
        return false;
    }
    const uint8_t* data = reinterpret_cast<const uint8_t*>(blob.data());
    out.type = static_cast<DataType>(data[0]);
    out.precision = readUint32LE(data + 1);
    out.scale = readUint32LE(data + 5);
    return true;
}

std::string encodeUuidList(const std::vector<ID>& ids) {
    std::string out;
    out.resize(4);
    sblr::writeInt32(reinterpret_cast<uint8_t*>(out.data()),
                     static_cast<uint32_t>(ids.size()));
    for (const auto& id : ids) {
        size_t offset = out.size();
        out.resize(offset + sizeof(ID));
        std::memcpy(&out[offset], id.bytes.data(), sizeof(ID));
    }
    return out;
}

bool decodeUuidList(const std::string& blob, std::vector<ID>& out) {
    out.clear();
    if (blob.size() < 4) {
        return false;
    }
    const uint8_t* data = reinterpret_cast<const uint8_t*>(blob.data());
    uint32_t count = readUint32LE(data);
    size_t expected = 4 + static_cast<size_t>(count) * sizeof(ID);
    if (blob.size() < expected) {
        return false;
    }
    out.reserve(count);
    size_t offset = 4;
    for (uint32_t i = 0; i < count; ++i) {
        ID id{};
        std::memcpy(id.bytes.data(), data + offset, sizeof(ID));
        out.push_back(id);
        offset += sizeof(ID);
    }
    return true;
}

