// Security policy epochs (Plan 03)

auto CatalogManager::getSecurityPolicyEpoch(uint64_t& epoch_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (security_policy_epoch_table_page_ == 0)
    {
        Status status = allocateCatalogPage(security_policy_epoch_table_page_, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to allocate security policy epoch table page");
            return status;
        }
        status = writeCatalogRoot(ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to persist security policy epoch table page");
            return status;
        }
    }

    if (security_policy_epoch_ == 0)
    {
        auto predicate = [](const SecurityPolicyEpochRecord& rec) {
            return rec.is_valid;
        };
        auto result = findRecordInHeapPage<SecurityPolicyEpochRecord>(
            security_policy_epoch_table_page_, predicate, ctx);
        if (result.status == Status::OK)
        {
            security_policy_epoch_ = result.record.global_epoch;
        }
        else
        {
            SecurityPolicyEpochRecord record{};
            record.global_epoch = 1;
            record.last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
            record.is_valid = 1;
            Status status = writeRecordToHeapPage(security_policy_epoch_table_page_, record, ctx);
            if (status != Status::OK)
            {
                SET_ERROR_CONTEXT(ctx, status, "Failed to initialize security policy epoch");
                return status;
            }
            security_policy_epoch_ = record.global_epoch;
        }
    }

    epoch_out = security_policy_epoch_;
    return Status::OK;
}

auto CatalogManager::bumpSecurityPolicyEpoch(uint64_t& epoch_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    uint64_t current_epoch = 0;
    Status status = getSecurityPolicyEpoch(current_epoch, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    uint64_t new_epoch = current_epoch + 1;
    auto predicate = [](const SecurityPolicyEpochRecord& rec) {
        return rec.is_valid;
    };
    auto result = findRecordInHeapPage<SecurityPolicyEpochRecord>(
        security_policy_epoch_table_page_, predicate, ctx);

    if (result.status == Status::OK)
    {
        SecurityPolicyEpochRecord updated = result.record;
        updated.global_epoch = new_epoch;
        updated.last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
        status = updateRecordInHeapPage(security_policy_epoch_table_page_, result.slot_index,
                                        updated, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to update security policy epoch");
            return status;
        }
    }
    else
    {
        SecurityPolicyEpochRecord record{};
        record.global_epoch = new_epoch;
        record.last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();
        record.is_valid = 1;
        status = writeRecordToHeapPage(security_policy_epoch_table_page_, record, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to persist security policy epoch");
            return status;
        }
    }

    security_policy_epoch_ = new_epoch;
    epoch_out = new_epoch;
    return Status::OK;
}

auto CatalogManager::getTablePolicyEpoch(const ID& table_id, uint64_t& epoch_out,
                                         ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto it = table_cache_.find(table_id);
    if (it == table_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Table not found");
        return Status::NOT_FOUND;
    }
    epoch_out = it->second.policy_epoch;
    return Status::OK;
}

auto CatalogManager::bumpTablePolicyEpoch(const ID& table_id, uint64_t& epoch_out,
                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);
    auto it = table_cache_.find(table_id);
    if (it == table_cache_.end())
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Table not found");
        return Status::NOT_FOUND;
    }

    auto predicate = [&table_id](const TableRecord& rec) {
        return rec.is_valid && rec.table_id == table_id;
    };
    auto result = findRecordInHeapPage<TableRecord>(tables_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Table not found");
        return result.status;
    }

    uint64_t new_epoch = it->second.policy_epoch + 1;
    TableRecord updated = result.record;
    updated.policy_epoch = new_epoch;
    updated.last_modified_time = std::chrono::system_clock::now().time_since_epoch().count();

    Status status = updateRecordInHeapPage(tables_table_page_, result.slot_index, updated, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update table policy epoch");
        return status;
    }

    it->second.policy_epoch = new_epoch;
    it->second.last_modified_time = updated.last_modified_time;
    epoch_out = new_epoch;
    return Status::OK;
}

// Audit log persistence (Plan 03)

auto CatalogManager::appendAuditLog(const AuditEvent& event,
                                    const std::array<uint8_t, 32>& hash_prev,
                                    const std::array<uint8_t, 32>& hash_curr,
                                    ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (audit_log_table_page_ == 0)
    {
        Status status = allocateCatalogPage(audit_log_table_page_, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to allocate audit log table page");
            return status;
        }
        status = writeCatalogRoot(ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to persist audit log table page");
            return status;
        }
    }

    AuditLogRecord record{};
    record.event_id = event.event_id;
    record.timestamp = event.timestamp;
    record.event_type = static_cast<uint16_t>(event.event_type);
    record.success = event.success ? 1 : 0;
    record.session_id = event.session_id;
    record.authkey_id = event.authkey_id;
    record.user_id = event.user_id;
    record.role_id = event.role_id;
    record.target_user_id = event.target_user_id;
    record.object_id = event.object_id;

    std::string user_trunc = UTF8Utils::truncateToBytes(event.username, sizeof(record.username));
    std::memset(record.username, 0, sizeof(record.username));
    std::strncpy(record.username, user_trunc.c_str(), sizeof(record.username) - 1);

    std::string target_trunc = UTF8Utils::truncateToBytes(event.target_username, sizeof(record.target_username));
    std::memset(record.target_username, 0, sizeof(record.target_username));
    std::strncpy(record.target_username, target_trunc.c_str(), sizeof(record.target_username) - 1);

    std::string type_trunc = UTF8Utils::truncateToBytes(event.object_type, sizeof(record.object_type));
    std::memset(record.object_type, 0, sizeof(record.object_type));
    std::strncpy(record.object_type, type_trunc.c_str(), sizeof(record.object_type) - 1);

    std::string name_trunc = UTF8Utils::truncateToBytes(event.object_name, sizeof(record.object_name));
    std::memset(record.object_name, 0, sizeof(record.object_name));
    std::strncpy(record.object_name, name_trunc.c_str(), sizeof(record.object_name) - 1);

    record.details_oid = 0;
    if (!event.details.empty())
    {
        uint64_t xmin = 0;
        Status toast_status = storeStringInToast(event.details, xmin, record.details_oid, ctx);
        if (toast_status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store audit details in TOAST");
            return toast_status;
        }
    }

    std::memcpy(record.hash_prev, hash_prev.data(), hash_prev.size());
    std::memcpy(record.hash_curr, hash_curr.data(), hash_curr.size());
    record.is_valid = 1;

    Status status = writeRecordToHeapPage(audit_log_table_page_, record, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to persist audit log record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::queryAuditLog(const AuditQuery& query, std::vector<AuditEvent>& events_out,
                                   ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    events_out.clear();
    if (audit_log_table_page_ == 0)
    {
        return Status::OK;
    }

    uint64_t xmin = 0;
    std::vector<AuditEvent> events;
    auto filter = [](const AuditLogRecord& rec) { return rec.is_valid; };
    auto converter = [this, xmin, ctx](const AuditLogRecord& rec, AuditEvent& event) {
        const_cast<char&>(rec.username[sizeof(rec.username) - 1]) = '\0';
        const_cast<char&>(rec.target_username[sizeof(rec.target_username) - 1]) = '\0';
        const_cast<char&>(rec.object_type[sizeof(rec.object_type) - 1]) = '\0';
        const_cast<char&>(rec.object_name[sizeof(rec.object_name) - 1]) = '\0';

        event.event_id = rec.event_id;
        event.timestamp = rec.timestamp;
        event.event_type = static_cast<AuditEventType>(rec.event_type);
        event.success = rec.success != 0;
        event.session_id = rec.session_id;
        event.authkey_id = rec.authkey_id;
        event.user_id = rec.user_id;
        event.role_id = rec.role_id;
        event.target_user_id = rec.target_user_id;
        event.object_id = rec.object_id;
        event.username = rec.username;
        event.target_username = rec.target_username;
        event.object_type = rec.object_type;
        event.object_name = rec.object_name;

        event.details.clear();
        if (rec.details_oid != 0)
        {
            loadStringFromToast(rec.details_oid, xmin, event.details, ctx);
        }
    };

    Status status = readRecordsToVector<AuditLogRecord, AuditEvent>(
        audit_log_table_page_, events, filter, converter, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    for (const auto& event : events)
    {
        if (query.start_time > 0 && event.timestamp < query.start_time)
        {
            continue;
        }
        if (query.end_time > 0 && event.timestamp > query.end_time)
        {
            continue;
        }
        if (query.user_id.has_value())
        {
            if (std::memcmp(&event.user_id, &query.user_id.value(), sizeof(ID)) != 0)
            {
                continue;
            }
        }
        if (query.session_id.has_value())
        {
            if (std::memcmp(&event.session_id, &query.session_id.value(), sizeof(ID)) != 0)
            {
                continue;
            }
        }
        if (query.authkey_id.has_value())
        {
            if (std::memcmp(&event.authkey_id, &query.authkey_id.value(), sizeof(ID)) != 0)
            {
                continue;
            }
        }
        if (query.username.has_value() && event.username != query.username.value())
        {
            continue;
        }
        if (query.event_type.has_value() && event.event_type != query.event_type.value())
        {
            continue;
        }
        if (!query.object_name.empty() && event.object_name != query.object_name)
        {
            continue;
        }
        if (query.success.has_value() && event.success != query.success.value())
        {
            continue;
        }

        events_out.push_back(event);
    }

    if (query.descending)
    {
        std::sort(events_out.begin(), events_out.end(),
                  [](const AuditEvent& a, const AuditEvent& b) {
                      if (a.timestamp != b.timestamp)
                      {
                          return a.timestamp > b.timestamp;
                      }
                      return a.event_id > b.event_id;
                  });
    }
    else
    {
        std::sort(events_out.begin(), events_out.end(),
                  [](const AuditEvent& a, const AuditEvent& b) {
                      if (a.timestamp != b.timestamp)
                      {
                          return a.timestamp < b.timestamp;
                      }
                      return a.event_id < b.event_id;
                  });
    }

    size_t start_idx = std::min(static_cast<size_t>(query.offset), events_out.size());
    size_t end_idx = std::min(start_idx + query.limit, events_out.size());
    if (start_idx != 0 || end_idx != events_out.size())
    {
        std::vector<AuditEvent> paged;
        paged.reserve(end_idx - start_idx);
        for (size_t i = start_idx; i < end_idx; ++i)
        {
            paged.push_back(events_out[i]);
        }
        events_out.swap(paged);
    }

    return Status::OK;
}

auto CatalogManager::getAuditLogTail(uint64_t& last_event_id_out,
                                     std::array<uint8_t, 32>& last_hash_out,
                                     ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    last_event_id_out = 0;
    last_hash_out.fill(0);

    if (audit_log_table_page_ == 0)
    {
        return Status::OK;
    }

    BufferPool* bp = db_->buffer_pool();
    if (!bp)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "BufferPool not available");
        return Status::INVALID_ARGUMENT;
    }

    uint32_t current_page_id = audit_log_table_page_;
    while (current_page_id != 0)
    {
        void* page_buffer = nullptr;
        Status status = bp->pinPage(current_page_id, &page_buffer, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        auto* heap = reinterpret_cast<CatalogHeapPage*>(page_buffer);
        uint32_t offset = sizeof(CatalogHeapPage);
        for (uint32_t i = 0; i < heap->record_count; ++i)
        {
            auto* record = reinterpret_cast<AuditLogRecord*>(
                reinterpret_cast<uint8_t*>(page_buffer) + offset);
            if (record->is_valid && record->event_id >= last_event_id_out)
            {
                last_event_id_out = record->event_id;
                std::memcpy(last_hash_out.data(), record->hash_curr, last_hash_out.size());
            }
            offset += sizeof(AuditLogRecord);
        }

        uint32_t next_page = heap->next_page;
        bp->unpinPage(current_page_id, false, ctx);
        current_page_id = next_page;
    }

    return Status::OK;
}

// ============================================================================
// Dormant transaction persistence (Track 3.2)
// ============================================================================

auto CatalogManager::createDormantTransaction(DormantTransactionInfo& info,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (isZeroUuidLocal(info.dormant_id))
    {
        info.dormant_id = generateUuidV7();
    }

    if (dormant_transactions_table_page_ == 0)
    {
        PageManager *pm = db_->page_manager();
        if (pm == nullptr)
        {
            SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "PageManager not available");
            return Status::INVALID_ARGUMENT;
        }

        Status status = pm->allocatePage(dormant_transactions_table_page_, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to allocate dormant transactions table page");
            return status;
        }

        BufferPool *bp = db_->buffer_pool();
        void *page_buffer;
        status = bp->pinPage(dormant_transactions_table_page_, &page_buffer, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        memset(page_buffer, 0, db_->page_size());
        auto *heap = static_cast<CatalogHeapPage *>(page_buffer);
        heap->header.magic = K_MAGIC_SBRD;
        heap->header.version = 1;
        heap->header.page_type = PAGE_TYPE_HEAP;
        heap->header.page_size = db_->page_size();
        heap->header.page_id = dormant_transactions_table_page_;
        heap->header.flags = 0;
        memcpy(heap->header.database_uuid, db_->uuid().bytes.data(), 16);
        heap->header.generation = 1;
        heap->record_count = 0;
        heap->free_offset = sizeof(CatalogHeapPage);
        heap->next_page = 0;
        heap->reserved = 0;
        heap->header.free_space = db_->page_size() - sizeof(CatalogHeapPage);
        heap->header.item_count = 0;
        heap->header.free_offset = sizeof(CatalogHeapPage);

        status = bp->unpinPage(dormant_transactions_table_page_, true, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        status = writeCatalogRoot(ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto predicate = [&info](const DormantTransactionRecord& rec) {
        return rec.is_valid && rec.dormant_id == info.dormant_id;
    };
    auto existing = findRecordInHeapPage<DormantTransactionRecord>(
        dormant_transactions_table_page_, predicate, ctx);
    if (existing.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Dormant transaction already exists");
        return Status::FILE_EXISTS;
    }
    if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    DormantTransactionRecord record;
    memset(&record, 0, sizeof(record));
    record.dormant_id = info.dormant_id;
    record.attachment_id = info.attachment_id;
    record.proc_id = info.proc_id;
    record.txn_id = info.txn_id;
    record.session_id = info.session_id;
    record.user_id = info.user_id;
    record.session_user_id = info.session_user_id;
    record.role_id = info.role_id;
    record.isolation_level = info.isolation_level;
    record.access_mode = static_cast<uint8_t>(info.access_mode);
    record.wait_mode = static_cast<uint8_t>(info.wait_mode);
    record.autocommit_mode = info.autocommit_mode ? 1 : 0;
    record.lock_timeout_seconds = info.lock_timeout_seconds;
    record.current_schema_id = info.current_schema_id;

    uint64_t xmin = 0;
    Status toast_status = storeStringInToast(info.session_settings, xmin,
                                            record.session_settings_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store session settings in TOAST");
        return toast_status;
    }

    toast_status = storeStringInToast(info.last_statement_text, xmin,
                                      record.last_statement_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store last statement in TOAST");
        return toast_status;
    }

    record.last_statement_hash = info.last_statement_hash;
    record.last_statement_type = static_cast<uint8_t>(info.last_statement_type);
    record.last_statement_status = static_cast<uint8_t>(info.last_statement_status);
    record.state = static_cast<uint8_t>(info.state);
    record.start_time = info.start_time;
    record.last_activity_time = info.last_activity_time;
    record.dormant_since = info.dormant_since;
    record.lease_expires_at = info.lease_expires_at;
    record.last_statement_time = info.last_statement_time;
    record.last_rows_affected = info.last_rows_affected;
    record.last_error_code = info.last_error_code;
    memset(record.last_sqlstate, 0, sizeof(record.last_sqlstate));
    if (!info.last_sqlstate.empty())
    {
        std::string truncated = info.last_sqlstate.substr(0, 5);
        memcpy(record.last_sqlstate, truncated.c_str(), truncated.size());
    }
    record.server_instance_id = info.server_instance_id;
    record.is_valid = info.is_valid ? 1 : 0;

    Status status = writeRecordToHeapPage(dormant_transactions_table_page_, record, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write dormant transaction record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::getDormantTransaction(const ID& dormant_id, DormantTransactionInfo& info_out,
                                           ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (dormant_transactions_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Dormant transaction table not initialized");
        return Status::NOT_FOUND;
    }

    auto predicate = [&dormant_id](const DormantTransactionRecord& rec) {
        return rec.is_valid && rec.dormant_id == dormant_id;
    };
    auto result = findRecordInHeapPage<DormantTransactionRecord>(
        dormant_transactions_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Dormant transaction not found");
        return result.status;
    }

    const DormantTransactionRecord& rec = result.record;
    info_out.dormant_id = rec.dormant_id;
    info_out.attachment_id = rec.attachment_id;
    info_out.proc_id = rec.proc_id;
    info_out.txn_id = rec.txn_id;
    info_out.session_id = rec.session_id;
    info_out.user_id = rec.user_id;
    info_out.session_user_id = rec.session_user_id;
    info_out.role_id = rec.role_id;
    info_out.isolation_level = rec.isolation_level;
    info_out.access_mode = static_cast<DormantAccessMode>(rec.access_mode);
    info_out.wait_mode = static_cast<DormantWaitMode>(rec.wait_mode);
    info_out.autocommit_mode = rec.autocommit_mode != 0;
    info_out.lock_timeout_seconds = rec.lock_timeout_seconds;
    info_out.current_schema_id = rec.current_schema_id;

    uint64_t xmin = 0;
    info_out.session_settings.clear();
    info_out.last_statement_text.clear();
    if (rec.session_settings_oid != 0)
    {
        loadStringFromToast(rec.session_settings_oid, xmin, info_out.session_settings, ctx);
    }
    if (rec.last_statement_oid != 0)
    {
        loadStringFromToast(rec.last_statement_oid, xmin, info_out.last_statement_text, ctx);
    }

    info_out.last_statement_hash = rec.last_statement_hash;
    info_out.last_statement_type = static_cast<DormantStatementType>(rec.last_statement_type);
    info_out.last_statement_status = static_cast<DormantStatementStatus>(rec.last_statement_status);
    info_out.state = static_cast<DormantTransactionState>(rec.state);
    info_out.start_time = rec.start_time;
    info_out.last_activity_time = rec.last_activity_time;
    info_out.dormant_since = rec.dormant_since;
    info_out.lease_expires_at = rec.lease_expires_at;
    info_out.last_statement_time = rec.last_statement_time;
    info_out.last_rows_affected = rec.last_rows_affected;
    info_out.last_error_code = rec.last_error_code;
    info_out.last_sqlstate.assign(
        rec.last_sqlstate, strnlen(rec.last_sqlstate, sizeof(rec.last_sqlstate)));
    info_out.server_instance_id = rec.server_instance_id;
    info_out.is_valid = rec.is_valid != 0;

    return Status::OK;
}

auto CatalogManager::updateDormantTransaction(const DormantTransactionInfo& info,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (dormant_transactions_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Dormant transaction table not initialized");
        return Status::NOT_FOUND;
    }

    if (isZeroUuidLocal(info.dormant_id))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Dormant transaction ID is required");
        return Status::INVALID_ARGUMENT;
    }

    DormantTransactionRecord updated;
    memset(&updated, 0, sizeof(updated));
    updated.dormant_id = info.dormant_id;
    updated.attachment_id = info.attachment_id;
    updated.proc_id = info.proc_id;
    updated.txn_id = info.txn_id;
    updated.session_id = info.session_id;
    updated.user_id = info.user_id;
    updated.session_user_id = info.session_user_id;
    updated.role_id = info.role_id;
    updated.isolation_level = info.isolation_level;
    updated.access_mode = static_cast<uint8_t>(info.access_mode);
    updated.wait_mode = static_cast<uint8_t>(info.wait_mode);
    updated.autocommit_mode = info.autocommit_mode ? 1 : 0;
    updated.lock_timeout_seconds = info.lock_timeout_seconds;
    updated.current_schema_id = info.current_schema_id;

    uint64_t xmin = 0;
    Status toast_status = storeStringInToast(info.session_settings, xmin,
                                            updated.session_settings_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store session settings in TOAST");
        return toast_status;
    }

    toast_status = storeStringInToast(info.last_statement_text, xmin,
                                      updated.last_statement_oid, ctx);
    if (toast_status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, toast_status, "Failed to store last statement in TOAST");
        return toast_status;
    }

    updated.last_statement_hash = info.last_statement_hash;
    updated.last_statement_type = static_cast<uint8_t>(info.last_statement_type);
    updated.last_statement_status = static_cast<uint8_t>(info.last_statement_status);
    updated.state = static_cast<uint8_t>(info.state);
    updated.start_time = info.start_time;
    updated.last_activity_time = info.last_activity_time;
    updated.dormant_since = info.dormant_since;
    updated.lease_expires_at = info.lease_expires_at;
    updated.last_statement_time = info.last_statement_time;
    updated.last_rows_affected = info.last_rows_affected;
    updated.last_error_code = info.last_error_code;
    memset(updated.last_sqlstate, 0, sizeof(updated.last_sqlstate));
    if (!info.last_sqlstate.empty())
    {
        std::string truncated = info.last_sqlstate.substr(0, 5);
        memcpy(updated.last_sqlstate, truncated.c_str(), truncated.size());
    }
    updated.server_instance_id = info.server_instance_id;
    updated.is_valid = info.is_valid ? 1 : 0;

    BufferPool *bp = db_->buffer_pool();
    uint32_t current_page_id = dormant_transactions_table_page_;
    while (current_page_id != 0)
    {
        void *page_buffer;
        Status status = bp->pinPage(current_page_id, &page_buffer, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        auto *heap = reinterpret_cast<CatalogHeapPage *>(page_buffer);
        uint32_t offset = sizeof(CatalogHeapPage);

        for (uint32_t i = 0; i < heap->record_count; ++i)
        {
            auto *record = reinterpret_cast<DormantTransactionRecord *>(
                reinterpret_cast<uint8_t *>(page_buffer) + offset);

            if (record->is_valid && record->dormant_id == info.dormant_id)
            {
                memcpy(record, &updated, sizeof(DormantTransactionRecord));
                heap->header.generation++;
                return bp->unpinPage(current_page_id, true, ctx);
            }

            offset += sizeof(DormantTransactionRecord);
        }

        uint32_t next_page = heap->next_page;
        bp->unpinPage(current_page_id, false, ctx);
        current_page_id = next_page;
    }

    SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Dormant transaction not found");
    return Status::NOT_FOUND;
}

auto CatalogManager::deleteDormantTransaction(const ID& dormant_id,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (dormant_transactions_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Dormant transaction table not initialized");
        return Status::NOT_FOUND;
    }

    BufferPool *bp = db_->buffer_pool();
    uint32_t current_page_id = dormant_transactions_table_page_;
    while (current_page_id != 0)
    {
        void *page_buffer;
        Status status = bp->pinPage(current_page_id, &page_buffer, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        auto *heap = reinterpret_cast<CatalogHeapPage *>(page_buffer);
        uint32_t offset = sizeof(CatalogHeapPage);

        for (uint32_t i = 0; i < heap->record_count; ++i)
        {
            auto *record = reinterpret_cast<DormantTransactionRecord *>(
                reinterpret_cast<uint8_t *>(page_buffer) + offset);

            if (record->is_valid && record->dormant_id == dormant_id)
            {
                record->is_valid = 0;
                heap->header.generation++;
                return bp->unpinPage(current_page_id, true, ctx);
            }

            offset += sizeof(DormantTransactionRecord);
        }

        uint32_t next_page = heap->next_page;
        bp->unpinPage(current_page_id, false, ctx);
        current_page_id = next_page;
    }

    SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Dormant transaction not found");
    return Status::NOT_FOUND;
}

auto CatalogManager::listDormantTransactions(std::vector<DormantTransactionInfo>& dormants_out,
                                             ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    dormants_out.clear();

    if (dormant_transactions_table_page_ == 0)
    {
        return Status::OK;
    }

    uint64_t xmin = 0;
    auto filter = [](const DormantTransactionRecord& rec) { return rec.is_valid; };
    auto converter = [this, xmin, ctx](const DormantTransactionRecord& rec,
                                       DormantTransactionInfo& info) {
        info.dormant_id = rec.dormant_id;
        info.attachment_id = rec.attachment_id;
        info.proc_id = rec.proc_id;
        info.txn_id = rec.txn_id;
        info.session_id = rec.session_id;
        info.user_id = rec.user_id;
        info.session_user_id = rec.session_user_id;
        info.role_id = rec.role_id;
        info.isolation_level = rec.isolation_level;
        info.access_mode = static_cast<DormantAccessMode>(rec.access_mode);
        info.wait_mode = static_cast<DormantWaitMode>(rec.wait_mode);
        info.autocommit_mode = rec.autocommit_mode != 0;
        info.lock_timeout_seconds = rec.lock_timeout_seconds;
        info.current_schema_id = rec.current_schema_id;

        info.session_settings.clear();
        info.last_statement_text.clear();
        if (rec.session_settings_oid != 0)
        {
            loadStringFromToast(rec.session_settings_oid, xmin, info.session_settings, ctx);
        }
        if (rec.last_statement_oid != 0)
        {
            loadStringFromToast(rec.last_statement_oid, xmin, info.last_statement_text, ctx);
        }

        info.last_statement_hash = rec.last_statement_hash;
        info.last_statement_type = static_cast<DormantStatementType>(rec.last_statement_type);
        info.last_statement_status = static_cast<DormantStatementStatus>(rec.last_statement_status);
        info.state = static_cast<DormantTransactionState>(rec.state);
        info.start_time = rec.start_time;
        info.last_activity_time = rec.last_activity_time;
        info.dormant_since = rec.dormant_since;
        info.lease_expires_at = rec.lease_expires_at;
        info.last_statement_time = rec.last_statement_time;
        info.last_rows_affected = rec.last_rows_affected;
        info.last_error_code = rec.last_error_code;
        info.last_sqlstate.assign(
            rec.last_sqlstate, strnlen(rec.last_sqlstate, sizeof(rec.last_sqlstate)));
        info.server_instance_id = rec.server_instance_id;
        info.is_valid = rec.is_valid != 0;
    };

    return readRecordsToVector<DormantTransactionRecord, DormantTransactionInfo>(
        dormant_transactions_table_page_, dormants_out, filter, converter, ctx);
}

// ============================================================================
// Prepared transaction persistence (Track 2 - 2PC)
// ============================================================================

auto CatalogManager::createPreparedTransaction(PreparedTransactionInfo& info,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (info.gid.empty())
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Prepared transaction GID is required");
        return Status::INVALID_ARGUMENT;
    }

    if (info.txn_id == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Prepared transaction XID is required");
        return Status::INVALID_ARGUMENT;
    }

    if (isZeroUuidLocal(info.prepared_id))
    {
        info.prepared_id = generateUuidV7();
    }

    if (isZeroUuidLocal(info.database_id))
    {
        info.database_id = db_->uuid();
    }

    if (prepared_transactions_table_page_ == 0)
    {
        Status status = allocateCatalogPage(prepared_transactions_table_page_, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to allocate prepared transactions table page");
            return status;
        }

        status = writeCatalogRoot(ctx);
        if (status != Status::OK)
        {
            return status;
        }
    }

    auto predicate = [&info](const PreparedTransactionRecord& rec) {
        if (!rec.is_valid)
        {
            return false;
        }
        std::string stored(rec.gid, strnlen(rec.gid, sizeof(rec.gid)));
        return stored == info.gid;
    };
    auto existing = findRecordInHeapPage<PreparedTransactionRecord>(
        prepared_transactions_table_page_, predicate, ctx);
    if (existing.status == Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, Status::FILE_EXISTS, "Prepared transaction already exists");
        return Status::FILE_EXISTS;
    }
    if (existing.status != Status::NOT_FOUND)
    {
        return existing.status;
    }

    if (info.gid.size() >= sizeof(PreparedTransactionRecord::gid))
    {
        SET_ERROR_CONTEXT(ctx, Status::INVALID_ARGUMENT, "Prepared transaction GID too long");
        return Status::INVALID_ARGUMENT;
    }

    PreparedTransactionRecord record;
    memset(&record, 0, sizeof(record));
    record.prepared_id = info.prepared_id;
    record.txn_id = info.txn_id;
    record.owner_id = info.owner_id;
    record.database_id = info.database_id;
    memcpy(record.gid, info.gid.c_str(), info.gid.size());
    record.gid[info.gid.size()] = '\0';
    record.prepared_time = info.prepared_time;
    record.is_valid = info.is_valid ? 1 : 0;

    Status status = writeRecordToHeapPage(prepared_transactions_table_page_, record, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write prepared transaction record");
        return status;
    }

    return Status::OK;
}

auto CatalogManager::getPreparedTransactionByGid(const std::string& gid,
                                                 PreparedTransactionInfo& info_out,
                                                 ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (prepared_transactions_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Prepared transactions table not initialized");
        return Status::NOT_FOUND;
    }

    auto predicate = [&gid](const PreparedTransactionRecord& rec) {
        if (!rec.is_valid)
        {
            return false;
        }
        std::string stored(rec.gid, strnlen(rec.gid, sizeof(rec.gid)));
        return stored == gid;
    };
    auto result = findRecordInHeapPage<PreparedTransactionRecord>(
        prepared_transactions_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Prepared transaction not found");
        return result.status;
    }

    const PreparedTransactionRecord& rec = result.record;
    info_out.prepared_id = rec.prepared_id;
    info_out.txn_id = rec.txn_id;
    info_out.owner_id = rec.owner_id;
    info_out.database_id = rec.database_id;
    info_out.gid.assign(rec.gid, strnlen(rec.gid, sizeof(rec.gid)));
    info_out.prepared_time = rec.prepared_time;
    info_out.is_valid = rec.is_valid != 0;

    return Status::OK;
}

auto CatalogManager::deletePreparedTransaction(const std::string& gid,
                                               ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    if (prepared_transactions_table_page_ == 0)
    {
        SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Prepared transactions table not initialized");
        return Status::NOT_FOUND;
    }

    BufferPool *bp = db_->buffer_pool();
    uint32_t current_page_id = prepared_transactions_table_page_;
    while (current_page_id != 0)
    {
        void *page_buffer;
        Status status = bp->pinPage(current_page_id, &page_buffer, ctx);
        if (status != Status::OK)
        {
            return status;
        }

        auto *heap = reinterpret_cast<CatalogHeapPage *>(page_buffer);
        uint32_t offset = sizeof(CatalogHeapPage);

        for (uint32_t i = 0; i < heap->record_count; ++i)
        {
            auto *record = reinterpret_cast<PreparedTransactionRecord *>(
                reinterpret_cast<uint8_t *>(page_buffer) + offset);

            if (record->is_valid)
            {
                std::string stored(record->gid, strnlen(record->gid, sizeof(record->gid)));
                if (stored == gid)
                {
                    record->is_valid = 0;
                    heap->header.generation++;
                    return bp->unpinPage(current_page_id, true, ctx);
                }
            }

            offset += sizeof(PreparedTransactionRecord);
        }

        uint32_t next_page = heap->next_page;
        bp->unpinPage(current_page_id, false, ctx);
        current_page_id = next_page;
    }

    SET_ERROR_CONTEXT(ctx, Status::NOT_FOUND, "Prepared transaction not found");
    return Status::NOT_FOUND;
}

auto CatalogManager::listPreparedTransactions(std::vector<PreparedTransactionInfo>& prepared_out,
                                              ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    prepared_out.clear();

    if (prepared_transactions_table_page_ == 0)
    {
        return Status::OK;
    }

    auto filter = [](const PreparedTransactionRecord& rec) { return rec.is_valid; };
    auto converter = [](const PreparedTransactionRecord& rec, PreparedTransactionInfo& info) {
        info.prepared_id = rec.prepared_id;
        info.txn_id = rec.txn_id;
        info.owner_id = rec.owner_id;
        info.database_id = rec.database_id;
        info.gid.assign(rec.gid, strnlen(rec.gid, sizeof(rec.gid)));
        info.prepared_time = rec.prepared_time;
        info.is_valid = rec.is_valid != 0;
    };

    return readRecordsToVector<PreparedTransactionRecord, PreparedTransactionInfo>(
        prepared_transactions_table_page_, prepared_out, filter, converter, ctx);
}

// Compute transitive closure of roles

auto CatalogManager::getEffectiveRoles(const ID& user_id, std::vector<ID>& roles_out,
                                       ErrorContext* ctx) -> Status
{
    // Security Phase 3.0: Implement transitive role-to-role grants (roles granted to roles)
    roles_out.clear();

    // Use BFS to find all roles (including transitive grants)
    std::unordered_set<ID> visited;
    std::queue<ID> to_process;
    to_process.push(user_id);
    visited.insert(user_id);

    while (!to_process.empty())
    {
        ID current_id = to_process.front();
        to_process.pop();

        // Get direct role memberships for current entity
        std::vector<RoleMembershipInfo> memberships;
        Status status = getUserRoles(current_id, memberships, ctx);
        if (status != Status::OK && status != Status::NOT_FOUND)
        {
            return status;
        }

        // Process each role
        for (const auto& membership : memberships)
        {
            if (visited.find(membership.role_id) == visited.end())
            {
                visited.insert(membership.role_id);
                roles_out.push_back(membership.role_id);
                to_process.push(membership.role_id);  // Process roles granted to this role
            }
        }
    }

    return Status::OK;
}

// Compute transitive closure of groups

auto CatalogManager::getEffectiveGroups(const ID& user_id, std::vector<ID>& groups_out,
                                        ErrorContext* ctx) -> Status
{
    groups_out.clear();

    // Use BFS to find all groups (including nested)
    std::unordered_set<ID> visited;
    std::queue<ID> to_process;
    to_process.push(user_id);
    visited.insert(user_id);

    while (!to_process.empty())
    {
        ID current_id = to_process.front();
        to_process.pop();

        // Get groups for current entity
        std::vector<ID> direct_groups;
        Status status = getUserGroups(current_id, direct_groups, ctx);
        if (status != Status::OK && status != Status::NOT_FOUND)
        {
            return status;
        }

        // Process each group
        for (const auto& group_id : direct_groups)
        {
            if (visited.find(group_id) == visited.end())
            {
                visited.insert(group_id);
                groups_out.push_back(group_id);
                to_process.push(group_id);  // Process nested groups
            }
        }
    }

    return Status::OK;
}

// Permission operations

auto CatalogManager::grantPermission(const ID& object_id, PermissionObjectType object_type,
                                     const ID& grantee_id, GranteeType grantee_type,
                                     uint32_t privileges, bool grant_option,
                                     const ID& grantor_id, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Check if permission already exists - if so, merge privileges
    auto predicate = [&](const PermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_, predicate, ctx);

    if (result.status == Status::OK)
    {
        // Update existing permission - merge privileges
        PermissionRecord updated_rec = result.record;
        updated_rec.privileges |= privileges;  // OR the privileges together
        if (grant_option) {
            updated_rec.grant_option = 1;
        }

        Status status = updateRecordInHeapPage(permissions_table_page_, result.slot_index,
                                              updated_rec, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to update permission record");
            return status;
        }

        uint64_t epoch = 0;
        Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
        if (epoch_status != Status::OK)
        {
            return epoch_status;
        }
        if (object_type == PermissionObjectType::TABLE)
        {
            uint64_t table_epoch = 0;
            Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
            if (table_status != Status::OK)
            {
                return table_status;
            }
        }

        DEBUG_LOG_DB("Updated permission on object " << object_id.toString());
        return Status::OK;
    }

    // Create new permission record
    PermissionRecord perm_rec;
    memset(&perm_rec, 0, sizeof(PermissionRecord));
    perm_rec.permission_id = generateUuidV7();
    perm_rec.object_id = object_id;
    perm_rec.object_type = static_cast<uint8_t>(object_type);
    perm_rec.grantee_id = grantee_id;
    perm_rec.grantee_type = static_cast<uint8_t>(grantee_type);
    perm_rec.privileges = privileges;
    perm_rec.grant_option = grant_option ? 1 : 0;
    perm_rec.grantor_id = grantor_id;
    perm_rec.created_time = std::chrono::system_clock::now().time_since_epoch().count();
    perm_rec.is_valid = 1;

    // Write to disk
    Status status = writeRecordToHeapPage(permissions_table_page_, perm_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to write permission record");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    if (object_type == PermissionObjectType::TABLE)
    if (result.record.object_type == static_cast<uint8_t>(ObjectType::TABLE))
    {
        uint64_t table_epoch = 0;
        Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
        if (table_status != Status::OK)
        {
            return table_status;
        }
    }

    DEBUG_LOG_DB("Granted permission on object " << object_id.toString());
    return Status::OK;
}

auto CatalogManager::revokePermission(const ID& object_id, PermissionObjectType object_type,
                                      const ID& grantee_id, GranteeType grantee_type,
                                      uint32_t privileges, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    // Find permission record
    auto predicate = [&](const PermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               rec.grantee_id == grantee_id &&
               rec.grantee_type == static_cast<uint8_t>(grantee_type);
    };

    auto result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_, predicate, ctx);
    if (result.status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, result.status, "Permission not found");
        return result.status;
    }

    // Remove specified privileges
    PermissionRecord updated_rec = result.record;
    updated_rec.privileges &= ~privileges;  // Clear the specified bits

    // If no privileges remain, delete the record
    if (updated_rec.privileges == 0)
    {
        Status status = deleteRecordFromHeapPage<PermissionRecord>(
            permissions_table_page_, predicate, ctx);
        if (status != Status::OK)
        {
            SET_ERROR_CONTEXT(ctx, status, "Failed to delete permission record");
            return status;
        }

        uint64_t epoch = 0;
        Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
        if (epoch_status != Status::OK)
        {
            return epoch_status;
        }
        if (object_type == PermissionObjectType::TABLE)
        {
            uint64_t table_epoch = 0;
            Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
            if (table_status != Status::OK)
            {
                return table_status;
            }
        }

        DEBUG_LOG_DB("Revoked all permissions on object " << object_id.toString());
        return Status::OK;
    }

    // Update with reduced privileges
    Status status = updateRecordInHeapPage(permissions_table_page_, result.slot_index,
                                          updated_rec, ctx);
    if (status != Status::OK)
    {
        SET_ERROR_CONTEXT(ctx, status, "Failed to update permission record");
        return status;
    }

    uint64_t epoch = 0;
    Status epoch_status = bumpSecurityPolicyEpoch(epoch, ctx);
    if (epoch_status != Status::OK)
    {
        return epoch_status;
    }
    if (object_type == PermissionObjectType::TABLE)
    {
        uint64_t table_epoch = 0;
        Status table_status = bumpTablePolicyEpoch(object_id, table_epoch, ctx);
        if (table_status != Status::OK)
        {
            return table_status;
        }
    }

    DEBUG_LOG_DB("Revoked permission on object " << object_id.toString());
    return Status::OK;
}

// WP-5 EXEC-M5: Revoke permission with CASCADE support
auto CatalogManager::revokePermissionCascade(const ID& object_id, PermissionObjectType object_type,
                                             const ID& grantee_id, GranteeType grantee_type,
                                             uint32_t privileges, ErrorContext* ctx) -> Status
{
    // CASCADE means: revoke permissions from grantee AND from everyone
    // who received those permissions from the grantee (transitive revocation)

    // First, collect all permissions that were granted by the grantee
    std::vector<PermissionInfo> cascade_targets;

    // Need to find all permissions on this object where grantor_id == grantee_id
    auto find_cascade = [&](const PermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               rec.grantor_id == grantee_id &&
               (rec.privileges & privileges) != 0;  // Only matching privileges
    };

    // Scan all permissions to find cascade targets
    {
        std::lock_guard<CatalogMutex> lock(mutex_);
        for (uint16_t i = 0; i < 100; ++i)  // Reasonable limit
        {
            auto result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_, find_cascade, ctx);
            if (result.status != Status::OK)
            {
                break;  // No more matches
            }

            PermissionInfo info;
            info.permission_id = result.record.permission_id;
            info.object_id = result.record.object_id;
            info.object_type = static_cast<PermissionObjectType>(result.record.object_type);
            info.grantee_id = result.record.grantee_id;
            info.grantee_type = static_cast<GranteeType>(result.record.grantee_type);
            info.privileges = result.record.privileges & privileges;  // Only matching privs
            info.grantor_id = result.record.grantor_id;
            cascade_targets.push_back(info);

            // Mark as processed to avoid finding it again - temporarily clear matching privileges
            PermissionRecord updated = result.record;
            updated.privileges &= ~privileges;
            if (updated.privileges == 0)
            {
                deleteRecordFromHeapPage<PermissionRecord>(permissions_table_page_,
                    [&](const PermissionRecord& r) {
                        return r.permission_id == result.record.permission_id;
                    }, ctx);
            }
            else
            {
                updateRecordInHeapPage(permissions_table_page_, result.slot_index, updated, ctx);
            }
        }
    }

    // Now revoke the original permission from the grantee
    Status status = revokePermission(object_id, object_type, grantee_id, grantee_type, privileges, ctx);
    if (status != Status::OK && status != Status::NOT_FOUND)
    {
        return status;
    }

    // Recursively cascade to each recipient (but we already deleted them above, so we're done)
    // The cascade targets have already been handled in the loop above

    DEBUG_LOG_DB("Revoked permission with CASCADE on object " << object_id.toString()
                 << " (cascaded to " << cascade_targets.size() << " grantees)");
    return Status::OK;
}

auto CatalogManager::hasPermission(const ID& user_id, const ID& object_id,
                                   PermissionObjectType object_type, Privilege privilege,
                                   bool& has_perm_out, ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    has_perm_out = false;

    BasicUserInfo user;
    Status status = getUserBasicUnlocked(user_id, user, ctx);
    if (status != Status::OK)
    {
        return status;
    }

    if (user.is_superuser)
    {
        has_perm_out = true;
        return Status::OK;
    }

    uint32_t privilege_mask = static_cast<uint32_t>(privilege);

    // Check direct user permissions
    auto check_permission = [&](const PermissionRecord& rec) {
        return rec.is_valid &&
               rec.object_id == object_id &&
               (rec.privileges & privilege_mask) != 0;
    };

    // 1. Check direct user permissions
    auto predicate_user = [&](const PermissionRecord& rec) {
        return check_permission(rec) &&
               rec.grantee_id == user_id &&
               rec.grantee_type == static_cast<uint8_t>(GranteeType::USER);
    };

    auto result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_,
                                                          predicate_user, ctx);
    if (result.status == Status::OK)
    {
        has_perm_out = true;
        return Status::OK;
    }

    // 2. Check PUBLIC permissions
    auto predicate_public = [&](const PermissionRecord& rec) {
        return check_permission(rec) &&
               rec.grantee_type == static_cast<uint8_t>(GranteeType::PUBLIC);
    };

    result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_,
                                                     predicate_public, ctx);
    if (result.status == Status::OK)
    {
        has_perm_out = true;
        return Status::OK;
    }

    // 3. Check role permissions
    std::vector<ID> effective_roles;
    status = getEffectiveRoles(user_id, effective_roles, ctx);
    if (status == Status::OK)
    {
        for (const auto& role_id : effective_roles)
        {
            auto predicate_role = [&](const PermissionRecord& rec) {
                return check_permission(rec) &&
                       rec.grantee_id == role_id &&
                       rec.grantee_type == static_cast<uint8_t>(GranteeType::ROLE);
            };

            result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_,
                                                            predicate_role, ctx);
            if (result.status == Status::OK)
            {
                has_perm_out = true;
                return Status::OK;
            }
        }
    }

    // 4. Check group permissions
    std::vector<ID> effective_groups;
    status = getEffectiveGroups(user_id, effective_groups, ctx);
    if (status == Status::OK)
    {
        for (const auto& group_id : effective_groups)
        {
            auto predicate_group = [&](const PermissionRecord& rec) {
                return check_permission(rec) &&
                       rec.grantee_id == group_id &&
                       rec.grantee_type == static_cast<uint8_t>(GranteeType::GROUP);
            };

            result = findRecordInHeapPage<PermissionRecord>(permissions_table_page_,
                                                            predicate_group, ctx);
            if (result.status == Status::OK)
            {
                has_perm_out = true;
                return Status::OK;
            }
        }
    }

    // No permission found
    return Status::OK;
}

auto CatalogManager::getObjectPermissions(const ID& object_id, PermissionObjectType object_type,
                                          std::vector<PermissionInfo>& permissions_out,
                                          ErrorContext* ctx) -> Status
{
    std::lock_guard<CatalogMutex> lock(mutex_);

    permissions_out.clear();

    auto filter = [&object_id](const PermissionRecord& rec) {
        return rec.is_valid && rec.object_id == object_id;
    };

    auto converter = [](const PermissionRecord& rec, PermissionInfo& info) {
        info.permission_id = rec.permission_id;
        info.object_id = rec.object_id;
        info.object_type = static_cast<PermissionObjectType>(rec.object_type);
        info.grantee_id = rec.grantee_id;
        info.grantee_type = static_cast<GranteeType>(rec.grantee_type);
        info.privileges = rec.privileges;
        info.grant_option = rec.grant_option != 0;
        info.grantor_id = rec.grantor_id;
        info.created_time = rec.created_time;
    };

    return readRecordsToVector<PermissionRecord, PermissionInfo>(
        permissions_table_page_, permissions_out, filter, converter, ctx);
}

